using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Windows.Forms;
internal sealed class ReleaseFile {public string Path{get;set;}public string Sha256{get;set;}public long Bytes{get;set;}}
internal sealed class ReleaseInfo {public int SchemaVersion{get;set;}public int MinDataFormat{get;set;}public int MaxDataFormat{get;set;}public string Version{get;set;}public List<ReleaseFile> Files{get;set;}}
internal static class VersionStore {
 internal static string ReleasePath(string root){return Path.Combine(root,"build","release.json");}
 internal static void VerifyRelease(string root,string hash,int format){root=DataLocation.SafePath(root);string p=ReleasePath(root);if(Common.Hash(p)!=hash)throw new InvalidDataException("程序构建清单身份不符");var r=DataLocation.ReadSmall<ReleaseInfo>(p,65536);if(r==null||(r.SchemaVersion!=1&&r.SchemaVersion!=2)||r.Files==null||r.Files.Count<5||r.Files.Count>40||format<r.MinDataFormat||format>r.MaxDataFormat)throw new InvalidDataException("程序不兼容当前数据格式；未恢复任何旧备份");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var f in r.Files){if(!FaultSafety.SafeRelative(f.Path)||!names.Add(f.Path)||!PackageAnalysis.HashText(f.Sha256))throw new InvalidDataException("构建清单路径或哈希无效或重复");string file=Path.GetFullPath(Path.Combine(root,f.Path));if(!LocalImport.Under(file,root))throw new InvalidDataException("清单越界");LocalImport.NoLinks(file);if(new FileInfo(file).Length!=f.Bytes||Common.Hash(file)!=f.Sha256)throw new InvalidDataException("程序文件缺失或变化："+f.Path);}var required=new[]{"build/LocalWallpaper.exe","build/WallpaperLocalTool.exe","build/WallpaperVersionTool.exe","build/runtime-manifest.json","rules/runtime-components.json","rules/v3-structure-families.json"};foreach(string n in required)if(!names.Contains(n))throw new InvalidDataException("构建清单缺少必需文件："+n);if(r.SchemaVersion==1&&!names.Contains("build/data-location.json"))throw new InvalidDataException("旧版构建清单缺少必需数据绑定：build/data-location.json");if(r.SchemaVersion==2&&names.Contains("build/data-location.json"))throw new InvalidDataException("新版构建身份不能绑定到用户专属数据位置");RuntimeDelivery.Verify(root);}
 internal static string ConfigHash(){return File.Exists(DataLocation.ConfigPath)?Common.Hash(DataLocation.ConfigPath):null;}
 internal static void Publish(Deployment d,string expected){if(ConfigHash()!=expected)throw new IOException("当前程序/数据关联已变化，未覆盖");DataLocation.SafePath(DataLocation.ControlRoot);Directory.CreateDirectory(DataLocation.ControlRoot);string tmp=DataLocation.ConfigPath+"."+Guid.NewGuid().ToString("N")+".tmp";try{Common.SaveNew(tmp,d);var check=DataLocation.ReadSmall<Deployment>(tmp,16384);if(check.StoreId!=d.StoreId||check.DataRoot!=d.DataRoot)throw new InvalidDataException("位置配置写后核验失败");if(ConfigHash()!=expected)throw new IOException("提交前关联变化");if(expected==null)File.Move(tmp,DataLocation.ConfigPath);else File.Replace(tmp,DataLocation.ConfigPath,null);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 internal static void CheckLegacyTools(string workspace){
#if !TEST_BUILD
 foreach(var p in Process.GetProcessesByName("WallpaperLocalTool"))using(p){string path;try{path=p.MainModule.FileName;}catch{throw new IOException("发现本地工具但无法核验身份，暂不切换");}if(LocalImport.Under(path,workspace))throw new IOException("工作区本地工具仍在运行，请待其结束后切换");}
#endif
 }
 internal static Deployment Switch(string root,bool rollback){using(var gate=new UpgradeGate()){DataLocation.Phase=rollback?"检查程序回退兼容性":"验证新程序版本";var old=DataLocation.Load();DataLocation.Current=old;using(var lease=new DataLease(old.DataRoot)){CheckLegacyTools(Path.GetDirectoryName(Common.AppRoot));DataLocation.ValidateStore(old,true);string before=ConfigHash();string target=DataLocation.SafePath(root);if(rollback&&(!DataLocation.Same(target,old.PreviousRoot??old.ActiveRoot)))throw new InvalidDataException("只允许回退到记录中的上一个程序版本；未恢复备份");DataLocation.DataPath(old.DataRoot,target);string hash=Common.Hash(ReleasePath(target));VerifyRelease(target,hash,old.DataFormat);if(rollback&&hash!=old.PreviousReleaseSha256)throw new InvalidDataException("上一个程序已变化，停止回退");FirstUseSetup.EnsureVersionBinding(target,old);string id="switch-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8);string records=Path.Combine(DataLocation.ControlRoot,"switches");Directory.CreateDirectory(records);var next=new Deployment{SchemaVersion=1,DataFormat=old.DataFormat,DataRoot=old.DataRoot,StoreId=old.StoreId,ActiveRoot=target,ReleaseSha256=hash,PreviousRoot=DataLocation.Same(target,old.ActiveRoot)?old.PreviousRoot:old.ActiveRoot,PreviousReleaseSha256=DataLocation.Same(target,old.ActiveRoot)?old.PreviousReleaseSha256:old.ReleaseSha256,MigrationRecord=old.MigrationRecord,CommittedAt=DateTimeOffset.Now.ToString("o")};Common.SaveNew(Path.Combine(records,id+".before.json"),new{schemaVersion=1,operation=rollback?"compatible-program-rollback":"program-switch",before=old,after=next,dataFingerprint=DataMigration.Fingerprint(Path.Combine(old.DataRoot,"data"),()=>{}),dataRestored=false,backupRestored=false,committed=false});Publish(next,before);Common.SaveNew(Path.Combine(records,id+".committed.json"),new{committed=true,at=next.CommittedAt,dataRootUnchanged=true,backupRestored=false});return next;}}}
 internal static int Launch(bool restore){var d=DataLocation.Load();DataLocation.Current=d;Common.AppRoot=d.ActiveRoot;DataLocation.ValidateStore(d,false);VerifyRelease(d.ActiveRoot,d.ReleaseSha256,d.DataFormat);string exe=Path.Combine(d.ActiveRoot,"build","LocalWallpaper.exe");var info=new ProcessStartInfo(exe,restore?"--restore-last":""){UseShellExecute=false,WorkingDirectory=d.ActiveRoot};using(var p=Process.Start(info)){}return 0;}
}
internal static class VersionTool {
 static bool cancelled;static void Check(){if(cancelled)throw new OperationCanceledException("用户已取消迁移，未继续提交");}
 [STAThread]static int Main(string[] args){Console.CancelKeyPress+=(s,e)=>{e.Cancel=true;cancelled=true;};bool launch=args.Length==0||args.Length==1&&args[0]=="--restore-last";try{if(launch)return VersionStore.Launch(args.Length==1);object result;
  if(args.Length==4&&args[0]=="prepare")result=DataMigration.Prepare(args[1],args[2],args[3],Check);
  else if(args.Length==2&&args[0]=="complete-assets")result=DataMigration.CompleteAssets(args[1],Check);
  else if(args.Length==2&&args[0]=="commit")result=DataMigration.Commit(args[1],Check);
  else if(args.Length==2&&(args[0]=="switch"||args[0]=="rollback"))result=VersionStore.Switch(args[1],args[0]=="rollback");
  else if(args.Length==1&&args[0]=="status")result=new{deployment=DataLocation.Load(),configuration=DataLocation.ConfigPath};
  else if(args.Length==2&&args[0]=="verify"){int n=RuntimeDelivery.Verify(args[1]);VersionStore.VerifyRelease(args[1],Common.Hash(VersionStore.ReleasePath(args[1])),1);result=new{selfOwnedRuntimeFiles=n,programOwnedReleaseComplete=true,externalComponentsValidated=false,externalComponentsBundled=false,playbackTested=false};}
#if TEST_BUILD
  else if(args.Length==2&&args[0]=="test"){result=DataHomeSmoke.Run(args[1]);}
#endif
  else throw new ArgumentException("用法：status | verify 程序目录 | prepare 来源版本 新数据根 新程序目录 | commit 迁移记录 | switch 程序目录 | rollback 上一个程序目录");
  Console.OutputEncoding=new UTF8Encoding(false);Console.WriteLine(Common.Json.Serialize(new{ok=true,result=result}));return 0;
 }catch(Exception ex){DataLocation.Failure=ex.Message;DataLocation.Phase="迁移/版本切换未完成";if(launch){DataLocation.Emergency();return StartupHandoff.Show(ex);}try{DataLocation.Emergency();string folder=Path.Combine(Common.WorkRoot,"upgrade-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var f=FaultHandoffForm.Demo();f.Demo=false;f.Operation="迁移或切换版本";f.Stage=DataLocation.Phase;f.Category=FaultSafety.Category("environment");f.Reason=ex.Message;f.DataState="未执行备份恢复或覆盖原库。当前提交状态需核对位置配置与迁移记录。";f.CleanupState="本次同步工具已经返回；没有启动播放器。";var bundle=DiagnosticBundle.Build(folder,f,()=>{});Console.WriteLine(Common.Json.Serialize(new{ok=false,error=ex.Message,package=Path.Combine(Common.Root,bundle.PackageRelative)}));DiagnosticBundle.CleanOperation(folder);}catch{Console.WriteLine(Common.Json.Serialize(new{ok=false,error=ex.Message,package="诊断包未取得，原数据未自动恢复"}));}return 1;}}
}
